// Some portions generated by Claude
import type { Graph } from "./graph-types.ts";
import type { computeGraphLayout, LayoutOptions } from "./graph-layout-engine.ts";

type LayoutResult = Awaited<ReturnType<typeof computeGraphLayout>>;
type LayoutReply = { result: LayoutResult } | { error: string };
type LayoutWorker = Pick<Worker, "postMessage" | "terminate" | "onmessage" | "onerror" | "onmessageerror">;

/** One worker per active calculation. Termination cancels CPU work, not just delivery. */
export function startGraphLayout(
  graph: Graph,
  options: LayoutOptions = {},
  createWorker: () => LayoutWorker = () =>
    new Worker(new URL("./graph-layout-worker.ts", import.meta.url), { type: "module" }),
) {
  let worker: LayoutWorker | undefined;
  let settled = false;
  let rejectJob: (reason: Error) => void = () => {};
  const cleanup = () => {
    if (!worker) return;
    worker.onmessage = worker.onerror = worker.onmessageerror = null;
    worker.terminate();
    worker = undefined;
  };
  const promise = new Promise<LayoutResult>((resolve, reject) => {
    rejectJob = reject;
    const fail = (error: Error) => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(error);
    };
    try {
      worker = createWorker();
      worker.onmessage = (event: MessageEvent<LayoutReply>) => {
        if (settled) return;
        if ("error" in event.data) {
          fail(new Error(event.data.error));
          return;
        }
        settled = true;
        cleanup();
        resolve(event.data.result);
      };
      worker.onerror = () => fail(new Error("The graph layout worker failed."));
      worker.onmessageerror = () => fail(new Error("The graph layout result could not be read."));
      worker.postMessage({ graph, options });
    } catch (error) {
      fail(error instanceof Error ? error : new Error(String(error)));
    }
  });
  return {
    promise,
    cancel() {
      if (settled) return;
      settled = true;
      cleanup();
      rejectJob(new DOMException("Layout cancelled", "AbortError"));
    },
  };
}
